#python word scrambler. up to 10 letter words only.
import random

word = input("Enter a word (up to 10 letters): ")
if len(word) == 0 or len(word) > 10:
    print('Please enter a word with 1 to 10 letters.')
elif len(set(word)) == 1:
    print("Scrambled word:", word)
else:
    letters = list(word)
    scrambled = word

    while scrambled == word:
        random.shuffle(letters)
        scrambled = "".join(letters)

    print('Scrambled word:', scrambled)
